import React, { useState } from "react";
import {
  RouterProvider,
  createBrowserRouter,
  createRoutesFromElements,
  Route,
  Navigate,
} from "react-router-dom";
import Root, { ROUTES } from "./components/root/Root";
import { AppointmentsPage } from "./containers/appointmentsPage/AppointmentsPage";
import { ContactsPage } from "./containers/contactsPage/ContactsPage";

function App() {
  // Define state variables for contacts and appointments
  const [contacts, setContacts] = useState([]);
  const [appointments, setAppointments] = useState([]);

  // Callback function to add a new contact
  // Receives name, phone, and email and adds a new contact object
  const addContact = (name, phone, email) => {
    setContacts((prevContacts) => [
      ...prevContacts,
      { name, phone, email },
    ]);
  };

  // Callback function to add a new appointment
  // Receives title, contact, date, and time and adds a new appointment object
  const addAppointment = (title, contact, date, time) => {
    setAppointments((prevAppointments) => [
      ...prevAppointments,
      { title, contact, date, time },
    ]);
  };

  // Create a router using React Router v6.4+ features
  const router = createBrowserRouter(
    createRoutesFromElements(
      <Route path="/" element={<Root />}>
        {/* Redirect from the index to the contacts route */}
        <Route index element={<Navigate to={ROUTES.CONTACTS} replace />} />
        {/* Pass contacts and addContact as props to ContactsPage */}
        <Route
          path={ROUTES.CONTACTS}
          element={
            <ContactsPage contacts={contacts} addContact={addContact} />
          }
        />
        {/* Pass appointments, contacts, and addAppointment as props to AppointmentsPage */}
        <Route
          path={ROUTES.APPOINTMENTS}
          element={
            <AppointmentsPage
              appointments={appointments}
              contacts={contacts}
              addAppointment={addAppointment}
            />
          }
        />
      </Route>
    )
  );

  return <RouterProvider router={router} />;
}

export default App;
